(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:#a9d4ba;box-shadow:0 0 15px #a9d4ba}.fx-sticker{position:fixed;pointer-events:none;z-index:3;font-size:18px;opacity:0;animation:sticker 6s linear infinite}.fxr{opacity:0;transform:translateY(35px) rotate(.4deg);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.photo-card.selected{z-index:20;box-shadow:0 30px 80px #0006}.renewed:after{content:'🤝';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font-size:120px;animation:stamp .9s ease both}@keyframes sticker{0%{transform:translateY(110vh) rotate(0);opacity:0}15%{opacity:.65}100%{transform:translateY(-20vh) rotate(280deg);opacity:0}}@keyframes stamp{0%{opacity:0;transform:scale(.4) rotate(-12deg)}55%{opacity:1;transform:scale(1.1) rotate(4deg)}100%{opacity:0;transform:scale(1)}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);if(!reduce)for(let i=0;i<16;i++){const x=document.createElement('span');x.className='fx-sticker';x.textContent=['✦','★','♡','☻'][i%4];x.style.left=Math.random()*100+'%';x.style.animationDelay=-Math.random()*6+'s';b.appendChild(x)}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();